import{_ as t,c as s,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易圖通變卷四","description":"易圖通變 - 易圖通變卷四","frontmatter":{"title":"易圖通變卷四","description":"易圖通變 - 易圖通變卷四"},"headers":[],"relativePath":"classics/yitu-tongbian/005.md","filePath":"classics/yitu-tongbian/005.md"}'),r={name:"classics/yitu-tongbian/005.md"};function o(l,a,c,d,p,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易圖通變卷四",tabindex:"-1"},[i("易圖通變卷四 "),e("a",{class:"header-anchor",href:"#易圖通變卷四","aria-label":"Permalink to “易圖通變卷四”"},"​")],-1),e("p",null,"欽定四庫全書",-1),e("p",null,"宋雷思齊撰",-1),e("p",null,"河之有圖，虙犧則之以畫八卦，文王因之以系卦辭。歷代寶而傳之，自見於書之顧命、陳之東序者，而今乃謂其無，誰敢哉？然自記以思，古則雲其「出語之傷」，今則雲其「不出顧已」，皆意之而非其真見矣。秦火之後，獨見於書傳孔安國之雲而已。漢志雜以圖書，而徒謂其與書經緯表裡，易緯則徒又枝辭蔓引，愈違本旨，以至茫乎莫之究其有無形似之真為何如者，訖於唐、五季也。及宋之初，陳摶圖南始創古，推明象數，閔其賤用於陰陽家之起例，而蕪沒於乾鑿度，太一取其數以行九宮之法，起而著為龍圖，以行於世。愚幸及其全書，觀其離合出入，具於制數之說，若刳心而有以求羲、文之心者也。然實有不得於羲、文之心者，於本圖之外，就以五十有五之數別出一圖，自標之以為形洛書者，已是其初之失也。雖其縱橫錯綜、分合體用之意皆在本圖，而五十有五之數既離而別出，世遂捨本逐末，因疑圖、書並出，雖是若非，無以究其詣極，而徒長紛紛之論。至其傳及劉牧長民，因之泛出五十五圖，名以「鉤隱」，則又以增異。而時則李覯泰伯即駮其非是，然又自謂存其及見此三圖，則其首即所傳今謂河圖者，其二即所別出五十五數，漫標為形洛書者，其三又止於八卦方位而已。是長民不揣其本，其事固非，而泰伯亦元不識此之三，本之則一，而妄析以為三爾。自是已後，愈傳愈失，愈失愈鑿，至有因「河出圖，洛出書」，見於大傳，而並致疑大傅非孔子所作者，不知圖本非書，書本非圖。至其甚者，以五十五數之圖乃妄謂之河圖，而以圖南所傳之河圖反謂之洛書，顛倒迷繆，靡所底止。殊不明河圖八卦明著五十五數，實指以天數五，地數五，而其數自天一地二，以至天五地十，合而五十有五，有體有用，有虛有實，原始要終，而盡發於一圖，豈嘗別求合於洛書哉？洛書亦豈嘗謂五十五數哉？今圖南既別無義例辭說，誤以圖之五十五數別標一圖，以為洛書，是其傳疑之始也。原其初意，蓋由漢儒襲傳洪範初一之五行，其二曰火，四曰金，太玄準易實本之，亦以二為火、為南，四為金、為西。今河圖乃置二於西南，置四於東南，是火、金改次矣。既不敢遂改河圖，乃別以其五十五數析為洛書，而以洪範二火次於南，四金次於西，且以七隨二，九隨四，而易置其南、西焉。以故長民不識其由，至謂火、金易位也。夫離之數九，居正南為火，兌之數七，居正西為金，乃天地自然參伍以變之數，斷斷無以易之，豈容以漢儒任意比校洪範火金之二四得而移易之乎？況洪範只有五行之數，今增以七九，又以七隨二，九隨四，又何所本哉？若校以河圖之例，七附二，九附四，是七稽疑當隨二五事，「九五福」當隨四五紀，則成何義類也？二七、四九，徒論其數，無形象無方位可定，指空移易之則可。離兌之有方所，火金之有體用，豈天地之造化亦遂肯依附人之作為，亦為之變移乎？今圖南不謂圖書之數較然不可相同，而欲以背理之人為比而同之，截截自分界限，是得指失肩背矣。且河圖之出，非徒謂四象八卦之具文也，天地之體用固猶是也。離南象天，離中乃陰，陰所以降。坎北象地，坎中有陽，陽所以升。震陽在初，所以象陽木之東昇。兌陰在上，所以象陰金之西降。乾坤所以體天地，陰陽所以用造化，而二卦乃寄於西南西北之維，習於常見，是天地易位矣。不惟是也，筮法又以震、巽為木，乾、兌為金，坤、艮為土，而坎獨為水，離獨為火，則坎、離得專水火，而乾、坤乃不得專天地，亦猶火金之不可以執方求定也。坤二位於西南，乃地二生火；巽四位於東南，乃地四生金，皆陰也。而兌七位於西，離九位於南，皆陽也。是生數皆陰，必待陽數以成之也。地之生數自西而南，故坤而後巽。成數自南而西，故離而後兌。觀於火既熾而灰滅，是火既變而神化。金雖銷而質存，是金既化而精猶未變也。此火金之所以互變化者同而不同。故二七四、九之數，自是參伍錯綜之變，不可以執方究其竟也。今五十五數之圖，以一二三四置於四方之內，而以六七八九隨置其外者，案其方而數之則可也，不知將何以循序迴環以運行之乎？況不知五與十者，特有數寄於四方之位而虛用之也。且五與十雖謂土數，五行家於土必以分王於四方辰戌醜未之位，醫家謂土為脾，以五氣之運，每運七十二日，總三百六十為期之例，特以土之七十二日四分之，各十八日於四時之附末，謂為脾之主事，醫於人至為切已。以土之日四分而試之，以為常驗，亦豈常專以土之五總之，而特設五於四方之外，與四方分位而別立之五以為中五哉？況筮法四營而成易，以十有八變而成卦，每變四營，總卦之成凡七十有二營，亦與醫說脗合。今圖乃分五離立，而特設異五於中位，指以為中，則為此中者，又將孰適於用乎？故餘以為圖南之別立五十五數標異，謂之「形洛書」者，是其初作已自失之矣。書之九疇，各疇自有成數，如一五行，二五事，猶或得以五行五用之數從而強推引之，至於五皇極，則已不可指實之為何物何事，而甚則九五福而附以六極，則將計九乎？計五福而兼計六極乎？皇極謂大中，而六極者其極又可謂中乎？皇極本非物非事，故可指之為中，今徒實以五點，而五點者乃遂得為中乎？疇自一至九，界界然各存本有之數，不知何自而可以合於五十有五之數，強謂其合者，蓋其人之妄也。若其後而至於以書謂圖，以圖謂書者，又妄人中之妄人也。此餘特謂圖則有數可通，而書則有疇類可數，而不可布之以為圖也。凡餘所以專守河圖者，非敢自謂親見羲文所以本之而作易者，而其五且十之數，橫斜旁正，相生相成之進退贏縮，一陰一陽之奇耦分合，八體二用之虛實變通，殆有造化神明莫窮之蘊，非人之所能為，而殆乎天地之自然者，宜其為羲文所以作易之本原也。竊嘗心潛力索，觸類引伸，變而通之，由門入蘊，謂獨得一全之體用，僭著其說。然與漢諸儒事事必強推五行以求合於春秋災異，傅會五十五數以為洛書者，實不敢謂然，不敢同也，世恐未悉。況此河圖或謂由易緯乾鑿度，謂太一取其數以行九宮，四正四維皆合十五。鄭康成又注引其所以行九宮者。至於環中之虛位，本非謂五，而乃謂實為五之中宮，固其緯注俱妄。又不知其為五若十，皆虛用以制其奇耦生成，雖有其數，實無其位也。然其所謂之太一者，與太極則無以異也。苟未識其然，記曰：「夫禮必本於太一，分而為天地，轉而為陰陽，變而為四時，列而為鬼神。」其理固與太極無以異也，自可旁通而無間然者，記經之屬也，因附諸傳後，以徵易圖通變卷四。",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
